import { useState } from "react";
import "./styles/DocuTag.css";

const SAMPLE_DOCS = [
  { id: 1, title: "Spring Boot 시작하기", tags: ["Spring", "Java"] },
  { id: 2, title: "React 훅 완전 정복", tags: ["React", "TypeScript"] },
  { id: 3, title: "JPA 연관관계 매핑", tags: ["JPA", "Java", "SQL"] },
  { id: 4, title: "Docker 컨테이너 배포", tags: ["Docker", "AWS"] },
  { id: 5, title: "Redis 캐싱 전략", tags: ["Redis", "Spring"] },
  { id: 6, title: "커서 기반 페이징 구현", tags: ["SQL", "Spring", "JPA"] },
  { id: 7, title: "Kubernetes 오케스트레이션", tags: ["Kubernetes", "Docker"] },
  { id: 8, title: "TypeScript 제네릭 활용", tags: ["TypeScript", "React"] },
];

export default function DocuTag() {
  const [search, setSearch] = useState("");
  const [searchTags, setSearchTags] = useState([]); // 검색바 아래 태그 목록
  const [newTagInput, setNewTagInput] = useState("");
  const [showTagInput, setShowTagInput] = useState(false);
  const [showWrite, setShowWrite] = useState(false);
  const [newTitle, setNewTitle] = useState("");
  const [newDocTags, setNewDocTags] = useState([]);
  const [docs, setDocs] = useState(SAMPLE_DOCS);

  const handleAddTag = () => {
  const trimmed = newTagInput.trim();
  if (!trimmed || searchTags.includes(trimmed)) return;
  setSearchTags((prev) => [...prev, trimmed]);
  setNewTagInput("");
  setShowTagInput(false);
};

  // 태그 삭제
  const handleRemoveTag = (tag) => {
    setSearchTags((prev) => prev.filter((t) => t !== tag));
  };

  // 검색: 제목
  const filteredDocs = docs.filter((doc) => {
  return doc.title.toLowerCase().includes(search.toLowerCase());
  });

  const handleWrite = () => {
    if (!newTitle.trim()) return;
    setDocs((prev) => [
      { id: Date.now(), title: newTitle, tags: newDocTags },
      ...prev,
    ]);
    setNewTitle("");
    setNewDocTags([]);
    setShowWrite(false);
  };

  const allTags = [...new Set(docs.flatMap((d) => d.tags))];

  return (
    <div style={{ fontFamily: "'Noto Sans KR', sans-serif", minHeight: "100vh", background: "#0f0f11", color: "#e8e6e1" }}>

      {/* Navbar */}
      <nav className="navbar">
        <span className="logo">DocuTag</span>
        <div className="search-wrap">
          <input
            className="search-input"
            placeholder="문서 제목 검색..."
            value={search}
            onChange={(e) => setSearch(e.target.value)}
          />
          <button className="btn-search">검색</button>
        </div>
        <button className="btn-write" onClick={() => setShowWrite(true)}>+ 작성</button>
      </nav>

      {/* Tag bar - 검색용, 필터 없음 */}
      <div className="tag-bar">
        <span className="tag-bar-label">태그</span>

        {searchTags.map((tag) => (
          <span key={tag} className="tag-chip">
            {tag}
            <button className="tag-remove" onClick={() => handleRemoveTag(tag)}>×</button>
          </span>
        ))}

        {/* 태그 추가 버튼 / 인풋 */}
        {showTagInput ? (
          <div className="tag-input-wrap">
            <input
              className="tag-input"
              placeholder="태그 입력..."
              value={newTagInput}
              onChange={(e) => setNewTagInput(e.target.value)}
              onKeyDown={(e) => e.key === "Enter" && handleAddTag()}
              autoFocus
            />
            <button className="tag-input-confirm" onClick={handleAddTag}>추가</button>
            <button className="tag-input-cancel" onClick={() => { setShowTagInput(false); setNewTagInput(""); }}>✕</button>
          </div>
        ) : (
          <button className="tag-add-btn" onClick={() => setShowTagInput(true)}>+ 태그</button>
        )}
      </div>

      {/* Main content */}
      <main className="main">
        <div className="result-info">
          <span>{filteredDocs.length}</span>개의 문서
          {searchTags.length > 0 && <> · <span>{searchTags.join(", ")}</span> 태그 검색 중</>}
        </div>
        <div className="grid">
          {filteredDocs.length === 0 ? (
            <div className="empty">검색 결과가 없습니다</div>
          ) : (
            filteredDocs.map((doc) => (
              <div className="card" key={doc.id}>
                <div className="card-title">{doc.title}</div>
                <div className="card-tags">
                  {doc.tags.map((tag) => (
                    <span
                      key={tag}
                      className={`card-tag${searchTags.includes(tag) ? " highlight" : ""}`}
                    >
                      {tag}
                    </span>
                  ))}
                </div>
              </div>
            ))
          )}
        </div>
      </main>

      {/* Write modal */}
      {showWrite && (
        <div className="modal-overlay" onClick={() => setShowWrite(false)}>
          <div className="modal" onClick={(e) => e.stopPropagation()}>
            <div className="modal-title">새 문서 작성</div>
            <input
              className="modal-input"
              placeholder="문서 제목"
              value={newTitle}
              onChange={(e) => setNewTitle(e.target.value)}
            />
            <div className="modal-tag-label">태그 선택</div>
            <div className="modal-tags">
              {allTags.map((tag) => (
                <button
                  key={tag}
                  className={`modal-tag-btn${newDocTags.includes(tag) ? " selected" : ""}`}
                  onClick={() =>
                    setNewDocTags((prev) =>
                      prev.includes(tag) ? prev.filter((t) => t !== tag) : [...prev, tag]
                    )
                  }
                >
                  {tag}
                </button>
              ))}
            </div>
            <div className="modal-actions">
              <button className="btn-cancel" onClick={() => setShowWrite(false)}>취소</button>
              <button className="btn-confirm" onClick={handleWrite} disabled={!newTitle.trim()}>
                작성
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}
